const data = await ctx.call("records", {});
console.log(data);

const totals = {};
const ownerByGroup = new Map();

if (Array.isArray(data.owners)) {
  for (const owner of data.owners) {
    if (typeof owner === "string") {
      totals[owner] = 0;
      ownerByGroup.set(owner, owner);
    } else {
      const name = owner.name ?? owner.owner ?? owner.label;
      const group = owner.group ?? owner.id ?? owner.key ?? name;
      if (name !== undefined) totals[name] = 0;
      if (group !== undefined && name !== undefined) ownerByGroup.set(group, name);
    }
  }
} else {
  for (const [group, name] of Object.entries(data.owners)) {
    totals[name] = 0;
    ownerByGroup.set(group, name);
  }
}

for (const record of data.records) {
  if (record.active) {
    const name = ownerByGroup.get(record.group);
    if (name !== undefined) totals[name] += record.value;
  }
}

ctx.done(totals);
